using System.IO;
using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class ReferencedGenericValueTypeMemberTests(ITestOutputHelper logger)
{
    private const string LibSource = """
        using MessagePack;

        namespace Lib
        {
            [MessagePackObject]
            public struct Item<T>
            {
                [Key(0)]
                public string Key { get; set; }
            }
        }
        """;

    private const string AppSource = """
        using MessagePack;
        using Lib;

        namespace App
        {
            [MessagePackObject]
            public sealed class Cmd
            {
                [Key(0)]
                public string Scope { get; set; }

                [Key(1)]
                public Item<int> Member { get; set; }
            }

            [GeneratedMessagePackResolver]
            partial class AppResolver
            {
            }
        }
        """;

    private static async Task<List<MetadataReference>> GetBaseReferencesAsync()
    {
        var refs = new List<MetadataReference>();
        refs.AddRange(await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None));
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        return refs;
    }

    private static async Task<MetadataReference> BuildLibAsync()
    {
        List<MetadataReference> refs = await GetBaseReferencesAsync();
        CSharpCompilation lib = CSharpCompilation.Create(
            "Lib",
            new[] { CSharpSyntaxTree.ParseText(LibSource) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using var ms = new MemoryStream();
        var emit = lib.Emit(ms);
        emit.Success.Should().BeTrue(string.Join(Environment.NewLine, emit.Diagnostics));
        return MetadataReference.CreateFromImage(ms.ToArray());
    }

    [Fact]
    public async Task ClosedGenericStructFromReferencedAssembly_NoGeneratorOrAnalyzerCrash()
    {
        MetadataReference libRef = await BuildLibAsync();
        var test = new VerifyCS.Test
        {
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        test.ReferenceAssemblies = ReferenceAssemblies.Net.Net80;
        test.TestState.Sources.Add(AppSource);
        test.TestState.AdditionalReferences.Add(libRef);
        await test.RunAsync();
    }

    [Fact]
    public async Task ClosedGenericStructFromReferencedAssembly_ResolverIsGenerated()
    {
        MetadataReference libRef = await BuildLibAsync();
        List<MetadataReference> refs = await GetBaseReferencesAsync();
        refs.Add(libRef);
        CSharpCompilation app = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(AppSource) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(app, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult result = driver.GetRunResult();

        foreach (Diagnostic d in generatorDiagnostics)
        {
            logger.WriteLine(d.ToString());
        }

        result.Results.Should().ContainSingle();
        result.Results[0].Exception.Should().BeNull();
        generatorDiagnostics.Should().NotContain(d => d.Id == "CS8785");
        result.GeneratedTrees.Should().Contain(t => t.GetText(CancellationToken.None).ToString().Contains("partial class AppResolver"));
    }
}
